export type Speaker = 'doctor' | 'patient'

// How the words entered the Consultation: typed or spoken by the doctor, or generated by the Simulated Patient.
export type TurnSource = 'typed' | 'voice' | 'simulated'

// How the system knows who spoke. Phase 1 knows by construction: only the doctor types at the workbench or speaks
// into its microphone, and the Simulated Patient's replies come from its agent. Phase 2 adds attribution for two
// human speakers sharing one microphone (voiceprint).
export type SpeakerAttribution = 'workbench-input' | 'workbench-microphone' | 'simulated-patient'

// Which speech recognizer turned the doctor's speech into text: Bailian Paraformer through the Worker, or the
// browser's Web Speech API when the Worker has no BAILIAN_TOKEN.
export type Recognizer = 'paraformer-realtime-v2' | 'web-speech'

// How a spoken doctor turn was recognized. `confidence` (0–1) is null when the recognizer reports none:
// paraformer-realtime-v2 returns no confidence score.
export interface VoiceCapture {
  recognizer: Recognizer
  durationMs: number
  confidence: number | null
}

// Doctor turns are always final. A patient turn is one reply attempt: pending until the Simulated Patient settles it.
export type TurnStatus = 'final' | 'pending' | 'failed'

export type PatientTurnFailure =
  | 'timeout'
  | 'llm-not-configured'
  | 'llm-error'
  | 'patient-unavailable'
  | 'encounter-ended'

export interface ConsultationTurn {
  turnId: string
  seq: number
  speaker: Speaker
  source: TurnSource
  attribution: SpeakerAttribution
  text: string
  // How a spoken doctor turn was recognized; null for typed and patient turns.
  voice: VoiceCapture | null
  status: TurnStatus
  // A patient turn's doctor turn, and which attempt at answering it this is.
  replyTo: string | null
  attempt: number
  createdAt: string
  settledAt: string | null
  // When a pending patient turn is due; past it, the turn fails and the lock releases.
  deadlineAt: string | null
  failure: PatientTurnFailure | null
}

export interface ConsultationResponse {
  turns: ConsultationTurn[]
}

export interface AskPatientRequest {
  // Chosen by the browser, so resending the same question after a dropped response records it once.
  clientTurnId: string
  text: string
  // A question the browser recognized from speech (Web Speech fallback). Paraformer turns never come over HTTP:
  // the Worker's voice pipeline records them itself.
  voice?: VoiceCapture
}

export interface AskPatientResponse {
  doctorTurn: ConsultationTurn
  patientTurn: ConsultationTurn
}

export interface RetryPatientTurnResponse {
  patientTurn: ConsultationTurn
}

export const MAX_QUESTION_LENGTH = 500

// The longest stretch of speech one doctor turn may carry.
export const MAX_SPEECH_DURATION_MS = 10 * 60_000

export function isVoiceCapture(value: unknown): value is VoiceCapture {
  const capture = value as Partial<VoiceCapture> | null
  return (
    typeof capture === 'object' &&
    capture !== null &&
    (capture.recognizer === 'paraformer-realtime-v2' || capture.recognizer === 'web-speech') &&
    typeof capture.durationMs === 'number' &&
    Number.isFinite(capture.durationMs) &&
    capture.durationMs >= 0 &&
    capture.durationMs <= MAX_SPEECH_DURATION_MS &&
    (capture.confidence === null ||
      (typeof capture.confidence === 'number' && capture.confidence >= 0 && capture.confidence <= 1))
  )
}
